WITH scope AS (SELECT c.* FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND c.relname LIKE 'haki_%'),
cols AS (SELECT a.attrelid, string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),CASE WHEN d.adbin IS NOT NULL THEN ' DEFAULT '||pg_get_expr(d.adbin,d.adrelid) ELSE '' END,CASE WHEN a.attnotnull THEN ' NOT NULL' ELSE '' END),E',\n' ORDER BY a.attnum) AS definitions FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid IN(SELECT oid FROM scope) AND a.attnum>0 AND NOT a.attisdropped GROUP BY a.attrelid)
SELECT jsonb_build_object(
'format','haki-logical-backup-v1','captured_at',now(),'server_version',version(),'scope','HAKI application public tables, schema, routines, triggers, and public Storage objects. Sessions are schema-only except separately archived expired rows. Supabase-managed Auth, secrets, provider settings and cron must be provisioned separately.',
'cleanup_cutoff',now()-interval '7 days',
'schema',jsonb_build_object(
'tables',(SELECT jsonb_agg(jsonb_build_object('name',s.relname,'ddl',format('CREATE TABLE public.%I (%s);',s.relname,c.definitions),'rls',s.relrowsecurity)) FROM scope s JOIN cols c ON c.attrelid=s.oid),
'constraints',(SELECT coalesce(jsonb_agg(format('ALTER TABLE public.%I ADD CONSTRAINT %I %s;',r.relname,c.conname,pg_get_constraintdef(c.oid))),'[]'::jsonb) FROM pg_constraint c JOIN scope r ON r.oid=c.conrelid),
'indexes',(SELECT coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid)||';'),'[]'::jsonb) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM scope) AND NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conindid=i.indexrelid)),
'routines',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'identity',format('public.%I(%s)',p.proname,pg_get_function_identity_arguments(p.oid)),'ddl',pg_get_functiondef(p.oid),'grants',(SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type)) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x))) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'haki_%'),
'triggers',(SELECT jsonb_agg(pg_get_triggerdef(oid)||';') FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN(SELECT oid FROM scope)),
'table_grants',(SELECT jsonb_agg(jsonb_build_object('table',s.relname,'role',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type)) FROM scope s CROSS JOIN LATERAL aclexplode(coalesce(s.relacl,acldefault('r',s.relowner))) x)),
'data',jsonb_build_object('haki_admins',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM public.haki_admins t),'haki_expenses',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM public.haki_expenses t),'haki_inventory',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM public.haki_inventory t),'haki_meta',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM public.haki_meta t),'haki_recovery_snapshots',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM public.haki_recovery_snapshots t),'haki_sales',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM public.haki_sales t),'haki_sales_history',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),'[]'::jsonb) FROM public.haki_sales_history t)),
'expired_sessions',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY token_hash),'[]'::jsonb) FROM public.haki_sessions t WHERE expires_at<now()-interval '7 days'),
'verification',jsonb_build_object('haki_admins',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''))) FROM public.haki_admins t),'haki_expenses',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''))) FROM public.haki_expenses t),'haki_inventory',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''))) FROM public.haki_inventory t),'haki_meta',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''))) FROM public.haki_meta t),'haki_recovery_snapshots',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''))) FROM public.haki_recovery_snapshots t),'haki_sales',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''))) FROM public.haki_sales t),'haki_sales_history',(SELECT jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,E'\n' ORDER BY to_jsonb(t)::text),''))) FROM public.haki_sales_history t)),
'storage_buckets',(SELECT jsonb_agg(jsonb_build_object('id',id,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types)) FROM storage.buckets WHERE id='haki-public'),
'storage_objects',(SELECT jsonb_agg(jsonb_build_object('id',id,'bucket_id',bucket_id,'name',name,'metadata',metadata,'created_at',created_at,'updated_at',updated_at) ORDER BY name) FROM storage.objects WHERE bucket_id='haki-public')
) AS backup;
